package kz.zeroops.api;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="enrollment_tokens") public class EnrollmentToken { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="server_id",nullable=false) private ManagedServer server; @Column(nullable=false,unique=true,length=64) private String tokenHash; @Column(nullable=false) private Instant expiresAt; private Instant usedAt; private Instant revokedAt; @Column(nullable=false) private Instant createdAt=Instant.now(); protected EnrollmentToken(){} public EnrollmentToken(ManagedServer server,String hash,Instant expiry){this.server=server;tokenHash=hash;expiresAt=expiry;} public ManagedServer getServer(){return server;} public String getTokenHash(){return tokenHash;} public Instant getExpiresAt(){return expiresAt;} public Instant getUsedAt(){return usedAt;} public Instant getRevokedAt(){return revokedAt;} public boolean active(){return usedAt==null&&revokedAt==null&&expiresAt.isAfter(Instant.now());} public void use(){usedAt=Instant.now();} public void revoke(){revokedAt=Instant.now();}}
